package com.example.claims.claim;

import java.math.BigDecimal;
import org.springframework.web.client.RestClient;

public final class RestExchangeRates implements ExchangeRates {
    record RateResponse(BigDecimal rate) {}

    private final RestClient client;

    public RestExchangeRates(RestClient client) {
        this.client = client;
    }

    @Override
    public BigDecimal rateToEur(String currency) {
        RateResponse response = client.get().uri("/rates/{currency}", currency)
                .retrieve().body(RateResponse.class);
        if (response == null || response.rate() == null) {
            throw new IllegalStateException("No rate returned for " + currency);
        }
        return response.rate();
    }
}
