package com.example.claims.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class Claim {
    static final BigDecimal APPROVAL_THRESHOLD_EUR = new BigDecimal("1000");

    private final ClaimId id;
    private final String employeeId;
    private final BigDecimal amount;
    private final String currency;
    private final BigDecimal amountEur;
    private final ClaimStatus status;

    private Claim(ClaimId id, String employeeId, BigDecimal amount, String currency,
                  BigDecimal amountEur, ClaimStatus status) {
        this.id = id;
        this.employeeId = employeeId;
        this.amount = amount;
        this.currency = currency;
        this.amountEur = amountEur;
        this.status = status;
    }

    public static Claim submit(ClaimId id, String employeeId, BigDecimal amount, String currency,
                               BigDecimal rateToEur) {
        if (id == null) throw new IllegalArgumentException("id required");
        if (employeeId == null || employeeId.isBlank()) throw new IllegalArgumentException("employeeId required");
        if (amount == null || amount.signum() <= 0) throw new IllegalArgumentException("amount must be positive");
        if (currency == null || currency.isBlank()) throw new IllegalArgumentException("currency required");
        if (rateToEur == null || rateToEur.signum() <= 0) throw new IllegalArgumentException("invalid rate");
        BigDecimal eur = amount.multiply(rateToEur).setScale(2, RoundingMode.HALF_UP);
        ClaimStatus status = eur.compareTo(APPROVAL_THRESHOLD_EUR) > 0
                ? ClaimStatus.PENDING_APPROVAL : ClaimStatus.APPROVED;
        return new Claim(id, employeeId, amount, currency.toUpperCase(), eur, status);
    }

    public ClaimId id() { return id; }
    public String employeeId() { return employeeId; }
    public BigDecimal amount() { return amount; }
    public String currency() { return currency; }
    public BigDecimal amountEur() { return amountEur; }
    public ClaimStatus status() { return status; }
}
